import{_ as t,o as i,c as s,a2 as d}from"./chunks/framework.Dsf4_p3t.js";const g=JSON.parse('{"title":"配置（gflags）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/configuration.md","filePath":"zh/guide/configuration.md","lastUpdated":1791275481000}'),a={name:"zh/guide/configuration.md"};function o(l,e,n,c,r,h){return i(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="配置-gflags" tabindex="-1">配置（gflags） <a class="header-anchor" href="#配置-gflags" aria-label="Permalink to &quot;配置（gflags）&quot;">​</a></h1><p>NeoFlux 使用 <a href="https://github.com/gflags/gflags" target="_blank" rel="noreferrer">gflags</a> 做运行时配置，用 <a href="https://github.com/google/glog" target="_blank" rel="noreferrer">glog</a> 记录日志。下列参数均为可选，在命令行传入：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr</span></span></code></pre></div><h2 id="渲染后端-编译期" tabindex="-1">渲染后端（编译期） <a class="header-anchor" href="#渲染后端-编译期" aria-label="Permalink to &quot;渲染后端（编译期）&quot;">​</a></h2><p>GPU 后端是 tgfx 自己的编译期选择，不是 NeoFlux 的概念。用 tgfx 原生的 <code>TGFX_USE_*</code> CMake 开关选定（每次构建恰好一个）；<code>thirdparty/CMakeLists.txt</code> 按 tgfx 的固定优先级（VULKAN &gt; D3D12 &gt; METAL &gt; OPENGL）消解，并导出唯一的 <code>TGFX_USE_*=1</code> 宏，保证 NeoFlux 源码与 tgfx 实际编译的后端一致。</p><table tabindex="0"><thead><tr><th>tgfx 开关</th><th>平台</th><th>说明</th></tr></thead><tbody><tr><td><code>TGFX_USE_OPENGL</code>（Apple 之外的默认）</td><td>Linux / Windows / Android</td><td>Linux <code>tgfx::EGLWindow</code>（X11）、Windows <code>tgfx::WGLWindow</code>、Android <code>tgfx::EGLWindow</code>。唯一经过完整测试的后端。</td></tr><tr><td><code>TGFX_USE_VULKAN</code></td><td>桌面</td><td>需要 Vulkan SDK 和支持 Vulkan 的驱动；tgfx 以 shaderc 构建。</td></tr><tr><td><code>TGFX_USE_D3D12</code></td><td>仅 Windows</td><td>需要 Windows SDK 的 D3D12 头文件。</td></tr><tr><td><code>TGFX_USE_METAL</code></td><td>仅 Apple</td><td>需要 Apple Metal 框架。</td></tr></tbody></table><p>用想要的后端配置并编译：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DTGFX_USE_METAL=ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DTGFX_USE_OPENGL=OFF</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">OpenGL 是唯一经过完整测试的后端</p><p>Vulkan、D3D12、Metal 还需要额外的系统依赖（shaderc、Vulkan SDK、Windows SDK 的 D3D12 头文件、Apple Metal 框架等），且尚未在 CI 中跑过。除非你有 明确的实验需求，否则保持 <code>TGFX_USE_OPENGL</code> 开启。</p></div><div class="warning custom-block"><p class="custom-block-title">这是编译期选择</p><p>没有运行时参数可以切换后端。如果想在 OpenGL 构建之后试试 Vulkan，需要重新 用 <code>-DTGFX_USE_VULKAN=ON -DTGFX_USE_OPENGL=OFF</code> 跑 CMake 并重新编译。</p></div><h2 id="完整参数表" tabindex="-1">完整参数表 <a class="header-anchor" href="#完整参数表" aria-label="Permalink to &quot;完整参数表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>含义</th></tr></thead><tbody><tr><td><code>--target_fps</code></td><td><code>int32</code></td><td><code>60</code></td><td>应用事件循环的目标帧率。</td></tr><tr><td><code>--idle_fps</code></td><td><code>int32</code></td><td><code>15</code></td><td>空闲心跳帧率：连续数帧无渲染请求且无协程/定时器任务后，循环降到此帧率（输入事件立即唤醒）；<code>0</code> 表示禁用空闲降频。</td></tr><tr><td><code>--render_queue_capacity</code></td><td><code>uint64</code></td><td><code>2048</code></td><td>SPSC 渲染命令环形队列容量，内部向上取整为 2 的幂（<code>std::bit_ceil</code>）；保留一个槽位，可用命令数 = <code>capacity - 1</code>。</td></tr><tr><td><code>--render_queue_drop_log_max</code></td><td><code>int32</code></td><td><code>10</code></td><td>每个进程最多打印多少次&quot;渲染队列已满、丢弃命令&quot;警告。超过后静默统计，不再刷屏。仅在诊断背压时调大。</td></tr><tr><td><code>--native_tuning</code></td><td><code>bool</code></td><td><code>true</code></td><td>平台原生调优层总开关；<code>false</code> 时所有入口均为 no-op。</td></tr><tr><td><code>--native_simd</code></td><td><code>bool</code></td><td><code>true</code></td><td>启用目标架构可用的手写 SIMD premultiply 内核。<code>false</code> 会强制使用可移植的标量路径；架构组宽仍是编译期 ABI 常量。</td></tr><tr><td><code>--native_render_rt_priority</code></td><td><code>int32</code></td><td><code>1</code></td><td>Linux/Android：渲染线程尝试的 SCHED_FIFO 优先级（1..99）。</td></tr><tr><td><code>--native_thread_nice</code></td><td><code>int32</code></td><td><code>-5</code></td><td>Linux/Android：渲染线程（降级路径）与 UI 线程尝试的 nice 值（-20..19）。</td></tr><tr><td><code>--native_bigcore_threshold_permille</code></td><td><code>int32</code></td><td><code>950</code></td><td>大核判定阈值（相对最快核频率的千分比，500..1000）。</td></tr><tr><td><code>--native_mmcss_profile</code></td><td><code>string</code></td><td><code>&quot;Games&quot;</code></td><td>Windows：渲染线程注册 MMCSS 使用的 profile。</td></tr><tr><td><code>--native_timer_period_ms</code></td><td><code>int32</code></td><td><code>1</code></td><td>Windows：timeBeginPeriod 请求的定时器精度（毫秒，<code>0</code> 表示不请求）。</td></tr><tr><td><code>--verbose_logging</code></td><td><code>bool</code></td><td><code>false</code></td><td>开启 <code>VLOG(1)</code> 并把 INFO 日志镜像到 stderr。</td></tr><tr><td><code>--logtostderr</code></td><td><code>bool</code></td><td><code>false</code></td><td>开启后所有日志写到 stderr 而非文件。</td></tr><tr><td><code>--log_dir</code></td><td><code>string</code></td><td><code>&quot;./logs&quot;</code></td><td><code>.log</code> 文件目录（自动创建），仅在未开启 <code>--logtostderr</code> 时生效。</td></tr></tbody></table><h3 id="idle-fps" tabindex="-1"><code>--idle_fps</code> <a class="header-anchor" href="#idle-fps" aria-label="Permalink to &quot;`--idle_fps`&quot;">​</a></h3><p>帧节拍有两个速率。只要应用还在产生工作（待恢复协程、定时器，或 <code>Application::MarkFrameDirty()</code> 发出的渲染请求），循环保持 <code>--target_fps</code> 全速；连续三帧无事可做后降到 <code>--idle_fps</code>，让空闲窗口的唤醒次数降到约 1/4；下一个渲染请求（任何输入事件）立即恢复全速。设 <code>--idle_fps=0</code> 可回到旧的恒速行为。</p><h3 id="原生调优-flags" tabindex="-1">原生调优 flags <a class="header-anchor" href="#原生调优-flags" aria-label="Permalink to &quot;原生调优 flags&quot;">​</a></h3><p><code>--native_*</code> 配置平台调优层<strong>尝试</strong>什么（见 <a href="./native-tuning">平台原生调优层</a>）。越界值会被钳制；OS 拒绝时一切尝试 依旧静默降级——这些 flag 只改变&quot;多激进&quot;，绝不改变正确性。 <code>--native_tuning=false</code> 是生产环境问题的单行逃生口。</p><h3 id="target-fps" tabindex="-1"><code>--target_fps</code> <a class="header-anchor" href="#target-fps" aria-label="Permalink to &quot;`--target_fps`&quot;">​</a></h3><p>设置 <code>EventLoop::SetTargetFps()</code>。循环在帧之间睡眠以满足帧率上限；输入事件与 <code>MarkFrameDirty()</code> 会提前唤醒。默认 <code>60</code>。</p><h3 id="render-queue-capacity" tabindex="-1"><code>--render_queue_capacity</code> <a class="header-anchor" href="#render-queue-capacity" aria-label="Permalink to &quot;`--render_queue_capacity`&quot;">​</a></h3><p>配置 <code>RenderLayer</code> 构造的 <code>SpscRingQueue&lt;RenderCommand&gt;</code>。内部用 <code>std::bit_ceil</code> 向上取整为 2 的幂，使下标回绕可用按位与完成。因保留一个槽位区分满/空，请求 <code>2048</code> 实际最多存 <code>2047</code> 条在途命令。若生产者追上消费者，本帧多余命令被丢弃 （限频警告）。</p><div class="warning custom-block"><p class="custom-block-title">仅在出现”render command queue full”警告时再调大</p><p>队列越大越占内存、增加呈现延迟。默认 <code>2048</code> 对一般 widget 树已足够。</p></div><h3 id="render-queue-drop-log-max" tabindex="-1"><code>--render_queue_drop_log_max</code> <a class="header-anchor" href="#render-queue-drop-log-max" aria-label="Permalink to &quot;`--render_queue_drop_log_max`&quot;">​</a></h3><p>渲染命令队列满载丢帧时，NeoFlux 会打一条 <code>WARNING</code> 日志。为避免在持续 背压下刷屏，每个进程最多打印前 <code>N</code> 条丢帧警告，之后的丢弃被静默计数。 默认 <code>10</code>。设为 <code>0</code> 可完全关闭丢帧警告。</p><h3 id="verbose-logging" tabindex="-1"><code>--verbose_logging</code> <a class="header-anchor" href="#verbose-logging" aria-label="Permalink to &quot;`--verbose_logging`&quot;">​</a></h3><p>一个便捷开关。开启后 NeoFlux 打开 <code>VLOG(1)</code>（<code>FLAGS_v = 1</code>）并把 INFO 级日志镜像到 stderr。逐帧布局转储（<code>VLOG(1) &lt;&lt; widgetname [x y w h]</code>）就靠它显示。</p><h3 id="logtostderr" tabindex="-1"><code>--logtostderr</code> <a class="header-anchor" href="#logtostderr" aria-label="Permalink to &quot;`--logtostderr`&quot;">​</a></h3><p>这是 glog 内建参数。当 glog 未与 gflags 集成构建时，NeoFlux 会在 gflags 解析之前 预扫描 <code>argv</code>，识别 <code>--logtostderr</code> / <code>--nologtostderr</code>（及 <code>-</code> 短横线形式）。默认关闭， 日志写入文件。</p><h3 id="log-dir" tabindex="-1"><code>--log_dir</code> <a class="header-anchor" href="#log-dir" aria-label="Permalink to &quot;`--log_dir`&quot;">​</a></h3><p>同样是 glog 内建参数，由同一套 argv 预扫描处理。同时接受 <code>--log_dir=路径</code> 与 <code>--log_dir 路径</code> 两种写法。写文件时默认 <code>./logs</code>，自动建目录，并追加 <code>.log</code> 扩展名； 目录无法创建时静默回退到 stderr。</p><h2 id="代码里打日志" tabindex="-1">代码里打日志 <a class="header-anchor" href="#代码里打日志" aria-label="Permalink to &quot;代码里打日志&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;glog/logging.h&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(INFO) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Application started&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(WARNING) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Font not found, using default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ERROR) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Rendering failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VLOG</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Detailed per-frame debug info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 配 --verbose_logging 显示</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">推荐的开发命令</p><p>本应用是 GUI 子系统二进制、没有控制台，运行时建议：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div></div><h2 id="完整示例" tabindex="-1">完整示例 <a class="header-anchor" href="#完整示例" aria-label="Permalink to &quot;完整示例&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neoflux_app.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_fps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">144</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">render_queue_capacity</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> `</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div><p>即目标 144 FPS、队列扩到 4096，并把详细日志输出到终端。</p><h2 id="编译时常量-core-config-h" tabindex="-1">编译时常量（<code>core/config.h</code>） <a class="header-anchor" href="#编译时常量-core-config-h" aria-label="Permalink to &quot;编译时常量（`core/config.h`）&quot;">​</a></h2><p>部分值是<strong>编译期</strong>的（编入二进制，不能运行时改）。它们定义在 <code>neoflux/include/neoflux/core/config.h</code> 中，为 <code>inline constexpr</code>：</p><table tabindex="0"><thead><tr><th>常量</th><th>默认值</th><th>含义</th></tr></thead><tbody><tr><td><code>config::kCacheLineSize</code></td><td><code>64</code></td><td>CPU 缓存行字节数。用于 SPSC 队列头尾分占不同缓存行（避免伪共享）。Apple M 系列/新 AMD 可用 <code>-DNEOFLUX_CACHE_LINE_SIZE=128</code> 覆盖。</td></tr></tbody></table><p>这是唯一的编译期常量：其余一切可调项都是 gflags（见上方 flag 总表）。 控件行为参数（长按时长、惯性阈值）由各自控件持有，不进全局配置。</p><h3 id="缓存行定尺寸与运行时检测" tabindex="-1">缓存行定尺寸与运行时检测 <a class="header-anchor" href="#缓存行定尺寸与运行时检测" aria-label="Permalink to &quot;缓存行定尺寸与运行时检测&quot;">​</a></h3><p><code>config::kCacheLineSize</code> 是用于把 SPSC 渲染队列头/尾填充到不同缓存行的 <strong>编译期</strong>对齐值（以避免伪共享）。它被编入二进制，运行时无法更改——但硬件 缓存行未必是 64 字节。因此平台原生调优层会在启动时<strong>校验</strong>这一假设： <code>neoflux::native::DetectCacheTopology()</code> 报告真实的一致性行大小（Linux/Android 读 sysfs、Windows 用 CPUID、Apple 用 <code>sysctl</code>）， <code>neoflux::native::VerifyCacheLineConfig()</code> 将其与 <code>config::kCacheLineSize</code> 比较，当硬件行比编入值更宽时<strong>只告警一次</strong>。</p><p>最典型的失配出现在 <strong>Apple M 系列</strong>：其 L1 数据缓存一致性行为 <strong>128 字节</strong>。 若构建停留在 64 字节默认值，队列头与尾各按 64 字节填充，相邻两个对象仍可能共占 同一条真实的 128 字节行，于是生产者与消费者持续在核间弹跳该行，伪共享并未因 填充而消除。若 <code>VerifyCacheLineConfig()</code> 打出该告警，请用检测到的尺寸重新构建：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Apple Silicon（128 字节行）</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_CACHE_LINE_SIZE=128</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><code>-DNEOFLUX_CACHE_LINE_SIZE=N</code> 定义 <code>NEOFLUX_CACHE_LINE_SIZE</code> 宏，<code>config.h</code> 读取它并赋给 <code>kCacheLineSize</code>——同一个符号，只是更宽，无需改动源码。在 64 字节 机器上过度对齐无害但会浪费一点内存，因此请设为检测器报告的尺寸，而不要更大。 完整的平台矩阵与自动启动钩子见 <a href="./native-tuning">平台原生调优层</a>。</p><div class="tip custom-block"><p class="custom-block-title">编译期 vs 运行时</p><p>只有必须为常量的值（如 <code>alignas</code> 实参）才放在 <code>config.h</code>。其余一切—— 包括 <code>--target_fps</code>、<code>--render_queue_capacity</code> 的默认值——都直接定义在 <code>core/flags.cpp</code>，全部运行时可调。</p></div>',45)])])}const k=t(a,[["render",o]]);export{g as __pageData,k as default};
